/*
 * A234639  Numbers n for which sigma(sigma(sigma(n))) is odd.
 * https://oeis.org/A234639
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   compute a(n) = the nth number in OEIS A234639 (numbers n for
 *            which σ(σ(σ(n))) is odd). The sequence is generated by checking
 *            each integer m ≥ 1 until we have collected the first n members.
 *            A simple sieve of σ values for integers up to MAX_N is used, and
 *            for larger arguments σ is computed by trial...
 * Range:     u8 n <= 3, u16 n <= 16, u32 n <= 404, u64 n <= 404,
 *            u128 n <= 404, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* ---------- constants and global tables ---------- */
#define MAX_N 5000000U   /* sieve limit: 5 000 000 */

static bool   initialized = false;
static uint32_t *spf = NULL;          /* smallest prime factor array */
static uint32_t *primes = NULL;       /* list of primes */
static size_t   prime_cnt = 0;        /* number of primes found */

/* ---------- cache of generated terms ---------- */
static seq_t  *terms = NULL;          /* array of generated terms */
static size_t  terms_len = 0;         /* number of terms stored */
static size_t  terms_cap = 0;         /* allocated capacity */

/* ---------- helper: build sieve up to MAX_N ---------- */
static void
init_sieve(void)
{
    /* allocate arrays */
    spf    = (uint32_t *)malloc((MAX_N + 1) * sizeof(uint32_t));
    primes = (uint32_t *)malloc((MAX_N / 10 + 1000) * sizeof(uint32_t));
    if (!spf || !primes) abort();  /* allocation failure */

    /* linear sieve */
    prime_cnt = 0;
    spf[0] = 0; spf[1] = 1;               /* 0 and 1 are special cases */
    for (uint32_t i = 2; i <= MAX_N; ++i) {
        if (spf[i] == 0) {
            spf[i] = i;
            if (prime_cnt == MAX_N / 10 + 1000)
                primes = (uint32_t *)realloc(primes,
                    (prime_cnt + 1000) * sizeof(uint32_t));
            primes[prime_cnt++] = i;
        }
        for (size_t j = 0; j < prime_cnt
                 && primes[j] <= spf[i]
                 && (uint64_t)i * primes[j] <= MAX_N; ++j) {
            spf[i * primes[j]] = primes[j];
        }
    }
    initialized = true;
}

/* ---------- compute σ(n)  (sum of divisors) ---------- */
static seq_t
sigma_u64(uint64_t n)
{
    if (n == 0) return 0;

    seq_t  sum = 1;
    if (n <= MAX_N) {
        uint64_t tmp = n;
        while (tmp > 1) {
            uint32_t p    = spf[(uint32_t)tmp];
            uint32_t exp  = 0;
            while (tmp % p == 0) {
                tmp /= p;
                ++exp;
            }
            /* term = (p^(exp+1)-1)/(p-1) */
            seq_t power = 1;
            for (uint32_t i = 0; i < exp; ++i) power *= (seq_t)p;
            seq_t num   = power * (seq_t)p;   /* p^(exp+1) */
            seq_t denom = (seq_t)(p - 1);
            seq_t term  = (num - 1) / denom;
            sum *= term;
        }
    } else { /* trial division using the precomputed primes */
        uint64_t tmp = n;
        for (size_t i = 0; i < prime_cnt && (uint64_t)primes[i]*primes[i] <= tmp; ++i) {
            uint32_t p = primes[i];
            if (tmp % p == 0) {
                uint32_t exp = 0;
                while (tmp % p == 0) {
                    tmp /= p;
                    ++exp;
                }
                seq_t power = 1;
                for (uint32_t j = 0; j < exp; ++j) power *= (seq_t)p;
                seq_t num   = power * (seq_t)p;
                seq_t denom = (seq_t)(p - 1);
                seq_t term  = (num - 1) / denom;
                sum *= term;
            }
        }
        if (tmp > 1) {        /* remaining prime factor with exponent 1 */
            seq_t term = (seq_t)tmp + 1;
            sum *= term;
        }
    }
    return sum;
}

/* ---------- main function for the sequence ---------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;    /* undefined for 0, but safe guard */

    /* initialize once */
    if (!initialized) init_sieve();

    static uint64_t current_candidate = 1;   /* next integer to test */

    /* generate terms until we reach nth term */
    while (terms_len < (size_t)n) {
        uint64_t m = current_candidate++;

        seq_t s1 = sigma_u64(m);
        seq_t s2 = sigma_u64((uint64_t)s1);
        seq_t s3 = sigma_u64((uint64_t)s2);

        if ((s3 % (seq_t)2) == 1) {    /* σ(σ(σ(m))) is odd */
            if (terms_len == terms_cap) {
                terms_cap = terms_cap * 2 + 10;
                terms = (seq_t *)realloc(terms, terms_cap * sizeof(seq_t));
                if (!terms) abort();   /* allocation failure */
            }
            terms[terms_len++] = (seq_t)m;
        }
    }
    return terms[n - 1];
}
